import{_ as o,o as a,c as r,a5 as t}from"./chunks/framework.C588jwcu.js";const h=JSON.parse('{"title":"Logger","description":"","frontmatter":{"title":"Logger","order":4},"headers":[],"relativePath":"ja/latest/tutorial/core/logger.md","filePath":"ja/latest/tutorial/core/logger.md","lastUpdated":1785683504000}'),d={name:"ja/latest/tutorial/core/logger.md"};function c(l,e,g,_,s,i){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="ロガー-knd-logger" tabindex="-1">ロガー KND_Logger <a class="header-anchor" href="#ロガー-knd-logger" aria-label="Permalink to &quot;ロガー KND_Logger&quot;">​</a></h1><h2 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h2><p>KND_Logger は Godot Logger の実装を基にしたログモジュールです。ログレベル、ログ形式、ログ出力、ログファイルなどをサポートし、Konado 実行時のログ情報を記録するために使用します。</p><h2 id="ログパス" tabindex="-1">ログパス <a class="header-anchor" href="#ログパス" aria-label="Permalink to &quot;ログパス&quot;">​</a></h2><p>ログファイルの論理パスは <code>user://konado_log.log</code> です。実際のディレクトリは現在の OS とプロジェクト名に応じて Godot が解決し、<code>OS.get_user_data_dir()</code> で確認できます。<code>LOG_FILE_PATH</code> は組み込み定数のため、保存先を変更する場合はカスタム版プラグインでこの定数を管理してください。</p><h2 id="画面オーバーレイログ" tabindex="-1">画面オーバーレイログ <a class="header-anchor" href="#画面オーバーレイログ" aria-label="Permalink to &quot;画面オーバーレイログ&quot;">​</a></h2><p>エラー発生時、会話シーンは画面上にログウィンドウを重ねて表示し、エラー情報を示してゲーム実行を中断します。この機能を無効にしたい場合は、<code>KND_DialogueManager</code> の <code>enable_overlay_log</code> プロパティを <code>false</code> に設定してください。</p><h2 id="ログコールバック" tabindex="-1">ログコールバック <a class="header-anchor" href="#ログコールバック" aria-label="Permalink to &quot;ログコールバック&quot;">​</a></h2><p><code>KND_Logger</code> のインスタンスは <code>error_caught(msg)</code> と <code>message_caught(message, error)</code> シグナルを送出します。<code>KND_DialogueManager</code> はシーンツリーに入ると内部ロガーを作成して Godot に登録し、<code>error_caught</code> で画面オーバーレイを制御します。ロガーはグローバルな自動読み込みではありません。別の <code>KND_Logger</code> を作成するカスタム連携では <code>OS.add_logger()</code> で登録し、解放前に <code>OS.remove_logger()</code> を呼び出して、重複記録や無効なインスタンスの残留を防いでください。</p>',9)])])}const u=o(d,[["render",c]]);export{h as __pageData,u as default};
